export const getProductImageUrl = (rawPath) => {
  if (!rawPath) return `${import.meta.env?.BASE_URL || './'}collection-women.png`;
  if (rawPath.startsWith('http')) return rawPath;
  const base = import.meta.env?.BASE_URL || './';
  const cleanBase = base.endsWith('/') ? base : `${base}/`;
  const cleanRel = rawPath.startsWith('/') ? rawPath.slice(1) : rawPath;
  const prefix = cleanRel.startsWith('images/') ? '' : 'images/';
  const fullRel = `${prefix}${cleanRel}`;
  const encoded = fullRel.split('/').map(seg => encodeURIComponent(seg)).join('/');
  return `${cleanBase}${encoded}`;
};

